'use strict';

function checkRecords(records) {
  if (!Array.isArray(records)) throw new TypeError('records must be an array');
  for (const record of records) {
    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError('each record must be an object');
    }
  }
}

function checkField(field) {
  if (typeof field !== 'string' || field.length === 0) throw new TypeError('field must be non-empty');
}

function mapLastBy(records, field) {
  checkRecords(records);
  checkField(field);
  const result = Object.create(null);
  for (const record of records) result[String(record[field])] = record;
  return result;
}

function fieldValues(records, field) {
  checkRecords(records);
  checkField(field);
  return records.map(record => record[field]);
}

function uniqueFieldValues(records, field) {
  checkRecords(records);
  checkField(field);
  return [...new Set(records.map(record => record[field]))];
}

function locateTicket(records, ticket) {
  checkRecords(records);
  return records.find(record => record.ticket === ticket) || null;
}

function encodeBatch(context, records, encoder) {
  checkRecords(records);
  if (typeof encoder !== 'function') throw new TypeError('encoder must be a function');
  const commands = [];
  const args = [];
  records.forEach((record, index) => {
    const part = encoder(context, record, index);
    if (!part || typeof part !== 'object' || Array.isArray(part) || typeof part.command !== 'string' || !Array.isArray(part.args)) {
      throw new TypeError('invalid encoder result');
    }
    commands.push(part.command);
    args.push(...part.args);
  });
  return { command: commands.join('\n'), args };
}

module.exports = { mapLastBy, fieldValues, uniqueFieldValues, locateTicket, encodeBatch };

