'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['encodeBatch', 'fieldValues', 'locateTicket', 'mapLastBy', 'uniqueFieldValues']);
const { mapLastBy, fieldValues, uniqueFieldValues, locateTicket, encodeBatch } = api;

const a = { id: 1, value: 'a', ticket: 'T1' };
const b = { id: 2, value: 'b', ticket: 'T2' };
const c = { id: 1, value: 'c', ticket: 'T1' };
const missing = { value: 'missing' };
const records = [a, b, c, missing];
const snapshot = records.slice();

const mapped = mapLastBy(records, 'id');
assert.strictEqual(Object.getPrototypeOf(mapped), null);
assert.strictEqual(mapped['1'], c);
assert.strictEqual(mapped['2'], b);
assert.strictEqual(mapped.undefined, missing);
assert.deepStrictEqual(records, snapshot);
const protoKey = { key: '__proto__' };
const protoMap = mapLastBy([protoKey], 'key');
assert.strictEqual(protoMap.__proto__, protoKey);

assert.deepStrictEqual(fieldValues(records, 'id'), [1, 2, 1, undefined]);
const fv = fieldValues(records, 'id');
fv[0] = 999;
assert.strictEqual(a.id, 1);

const nan1 = { v: NaN };
const nan2 = { v: NaN };
const minusZero = { v: -0 };
const plusZero = { v: 0 };
const absent1 = {};
const absent2 = {};
const unique = uniqueFieldValues([nan1, nan2, minusZero, plusZero, absent1, absent2], 'v');
assert.strictEqual(unique.length, 3);
assert.ok(Number.isNaN(unique[0]));
assert.ok(Object.is(unique[1], -0));
assert.strictEqual(unique[2], undefined);

assert.strictEqual(locateTicket(records, 'T1'), a);
assert.strictEqual(locateTicket(records, 'missing'), null);
assert.strictEqual(locateTicket([{ ticket: NaN }], NaN), null);
assert.strictEqual(locateTicket([], 'x'), null);
assert.deepStrictEqual(mapLastBy([], 'id'), Object.create(null));
assert.deepStrictEqual(fieldValues([], 'id'), []);
assert.deepStrictEqual(uniqueFieldValues([], 'id'), []);

assert.throws(() => mapLastBy(records, ''), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => mapLastBy(records, 1), TypeError);
for (const fn of [r => mapLastBy(r, 'id'), r => fieldValues(r, 'id'), r => uniqueFieldValues(r, 'id'), r => locateTicket(r, 'x')]) {
  assert.throws(() => fn(null), TypeError);
  assert.throws(() => fn([{} , null]), TypeError);
  assert.throws(() => fn([[]]), TypeError);
}

const calls = [];
const producedArgs = [];
const context = { prefix: 'P' };
const encoded = encodeBatch(context, [a, b], (ctx, record, index) => {
  calls.push([ctx, record, index]);
  const args = [record.id, { index }];
  producedArgs.push(args);
  return { command: ctx.prefix + index, args };
});
assert.deepStrictEqual(encoded.command, 'P0\nP1');
assert.deepStrictEqual(encoded.args, [1, { index: 0 }, 2, { index: 1 }]);
assert.deepStrictEqual(calls, [[context, a, 0], [context, b, 1]]);
assert.notStrictEqual(encoded.args, producedArgs[0]);
producedArgs[0].push('later');
assert.strictEqual(encoded.args.length, 4);
assert.deepStrictEqual(encodeBatch(context, [], () => { throw new Error('must not run'); }), { command: '', args: [] });
assert.throws(() => encodeBatch(context, records, null), TypeError);
assert.throws(() => encodeBatch(context, [null], () => ({ command: '', args: [] })), TypeError);
assert.throws(() => encodeBatch(context, [a], () => null), TypeError);
assert.throws(() => encodeBatch(context, [a], () => ({ command: 1, args: [] })), TypeError);
assert.throws(() => encodeBatch(context, [a], () => ({ command: 'x', args: 'no' })), TypeError);

